#include <iostream>
#include <fstream>
#include <string>
#include <ctime>

bool appendLog(const std::string& path, const std::string& message) {
    std::ofstream log(path, std::ios::app); // app: never truncates
    if (!log.is_open()) {                  // ALWAYS check
        std::cerr << "cannot open " << path << '\n';
