 char ch = text[i];
 if (ch=='a'||ch=='e'||ch=='i'||ch=='o'||ch=='u'||
 ch=='A'||ch=='E'||ch=='I'||ch=='O'||ch=='U') {
 count++;
 }
 }
 printf("Vowels: %d\n", count);
 return 0;
}
```

##### Output:
```text
