### 10.3 Common Coding Patterns

#### Pattern 1: Linear Search
Finds whether a target value exists in an array.
```c
#include <stdio.h>

int linearSearch(int arr[], int size, int target) {
    for (int i = 0; i < size; i++) {
        if (arr[i] == target) {
            return i; // Return matching index
        }
    }
    return -1; // Not found
}

int main(void) {
    int arr[] = {4, 2, 9, 7, 5};
    int size = sizeof(arr) / sizeof(arr[0]);
    int result = linearSearch(arr, size, 7);
    
    if (result != -1)
        printf("Found at index %d\n", result);
    else
        printf("Not found\n");
    return 0;
}
```
* **Time Complexity:** $O(n)$
* **Space Complexity:** $O(1)$

#### Pattern 2: Counting / Frequency Table
Counts character occurrences in $O(n)$ time using a fixed lookup bucket.
```c
#include <stdio.h>

int main(void) {
    char str[] = "programming";
    int freq[26] = {0}; // Letter frequencies

    for (int i = 0; str[i] != '\0'; i++) {
        freq[str[i] - 'a']++; // Map char code to 0-25
    }

    for (int i = 0; i < 26; i++) {
        if (freq[i] > 0) {
            printf("%c: %d\n", 'a' + i, freq[i]);
        }
    }
    return 0;
}
```
* **Time Complexity:** $O(n)$
* **Space Complexity:** $O(1)$ (constant auxiliary space)

#### Pattern 3: Palindrome Check (Two Pointer)
```c
#include <stdio.h>
#include <string.h>

int isPalindrome(char str[]) {
    int left = 0;
    int right = strlen(str) - 1;
    
    while (left < right) {
        if (str[left] != str[right]) {
            return 0; // Not a palindrome
        }
        left++;
        right--;
    }
    return 1; // Palindrome
}

int main(void) {
    char word[] = "madam";
    if (isPalindrome(word))
        printf("%s is a palindrome\n", word);
    else
        printf("%s is not a palindrome\n", word);
    return 0;
}
```

#### Pattern 4: String Reversal (In-Place)
```c
#include <stdio.h>
#include <string.h>

void reverseString(char str[]) {
    int left = 0;
    int right = strlen(str) - 1;
    while (left < right) {
        char temp = str[left];
        str[left] = str[right];
        str[right] = temp;
        left++;
        right--;
    }
}

int main(void) {
    char word[] = "hello";
    reverseString(word);
    printf("%s\n", word);
    return 0;
}
```

#### Pattern 5: Swapping Using Pointers (Pass-by-Address)
```c
#include <stdio.h>

void swap(int *a, int *b) {
    int temp = *a;
    *a = *b;
    *b = temp;
}

int main(void) {
    int x = 5, y = 10;
    swap(&x, &y);
    printf("x = %d, y = %d\n", x, y);
    return 0;
}
```
##### Expected Output:
```text
x = 10, y = 5
```

#### Pattern 6: Pointer Traversal of an Array
```c
#include <stdio.h>

int main(void) {
    int arr[] = {10, 20, 30, 40};
    int *p = arr;
    
    for (int i = 0; i < 4; i++) {
        printf("%d ", *(p + i)); // Pointer arithmetic
    }
    printf("\n");
    return 0;
}
```

#### Pattern 7: Structure Array Processing
```c
#include <stdio.h>

struct Student {
    char name[20];
    int marks;
};

int main(void) {
    struct Student students[3] = {
        {"Asha", 88},
        {"Vikram", 75},
        {"Neel", 92}
    };

    int topIndex = 0;
    for (int i = 1; i < 3; i++) {
        if (students[i].marks > students[topIndex].marks) {
            topIndex = i;
        }
    }

    printf("Topper: %s with %d marks\n", 
           students[topIndex].name, students[topIndex].marks);
    return 0;
}
```
##### Expected Output:
```text
Topper: Neel with 92 marks
```

#### Pattern 8: File Processing (Word Count)
```c
#include <stdio.h>

int main(void) {
    FILE *fp = fopen("sample.txt", "r");
    if (fp == NULL) {
        printf("Error opening file\n");
        return 1;
    }

    int count = 0;
    char ch;
    int inWord = 0;

    while ((ch = fgetc(fp)) != EOF) {
        if (ch == ' ' || ch == '\n' || ch == '\t') {
            inWord = 0;
        } else if (inWord == 0) {
            inWord = 1;
            count++;
        }
    }

    fclose(fp);
    printf("Word count: %d\n", count);
    return 0;
}
```

#### Pattern 9: Dynamic Memory Pattern (Resizable Array)
Implements dynamic array growth by doubling capacity.
```c
#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int capacity = 2;
    int count = 0;
    int *arr = (int *) malloc(capacity * sizeof(int));
    if (arr == NULL) return 1;

    for (int i = 1; i <= 5; i++) {
        if (count == capacity) {
            capacity *= 2;
            int *temp = (int *) realloc(arr, capacity * sizeof(int));
            if (temp == NULL) {
                free(arr);
                return 1;
            }
            arr = temp;
        }
        arr[count++] = i * 10;
    }

    for (int i = 0; i < count; i++) {
        printf("%d ", arr[i]);
    }
    printf("\n");

    free(arr);
    return 0;
}
```
##### Expected Output:
```text
10 20 30 40 50
```

